queries.cql:
// CrowdStrike CQL — Magecart WebSocket Card Data Exfiltration Detection
// Detects WebSocket connections from payment pages to recently registered masquerading domains
connection_type="websocket" request_url="wss://*"
| referer_page_type := case {
    match(referer_url, /checkout|payment|billing|cart\/complete|redsys|payplug/) => "payment_page" ;
    * => "other" ;
  }
| where referer_page_type == "payment_page"
| where destination_domain != "stripe.com"
    AND destination_domain != "paypal.com"
    AND destination_domain != "braintreegateway.com"
    AND destination_domain != "adyen.com"
    AND destination_domain != "authorize.net"
    AND destination_domain != "redsys.es"
    AND destination_domain != "payplug.com"
    AND destination_domain != "google-analytics.com"
    AND destination_domain != "hotjar.com"
    AND destination_domain != "jquery.com"
    AND destination_domain != "bootstrapcdn.com"
| masquerade_match := match(destination_domain, /analytics|cache|cdn|jquery|bootstrap|bundle|assets|hotjar|doubleclick|captcha|secure|referrer|wishlist|feedback|explorer|redsys/)
| token_match := match(request_url, /token=/)
| where (masquerade_match OR token_match)
    AND destination_domain_age_days <= 90
| ioc_match := in(destination_domain, values=[
    "bundle-feedback.com", "doubleclickcache.com", "analyticsgctm.com",
    "hotjarcdn.com", "firefoxcaptcha.com", "solutionjquery.com",
    "jquerybootstrap.com", "assetsbundle.com", "bundle-referrer.com",
    "categorywishlist.com", "cachesecure.com", "securedata-ns.com",
    "analysiscache.com", "newassetspro.com", "explorerpros.com", "redsysgate.com"
  ])
| risk_level := case {
    ioc_match => "critical" ;
    destination_domain_age_days <= 30 AND masquerade_match AND token_match => "critical" ;
    destination_domain_age_days <= 30 => "high" ;
    * => "high" ;
  }
| groupBy(destination_domain, function=[
    count(as=connection_count),
    collect([referer_url, request_url, destination_ip, destination_domain_age_days,
             destination_domain_registrar, ioc_match, risk_level, session_id])
  ])
| sort(connection_count, order=desc)
